.movement_type=N''purchase_return_cancel'' AND i.balance_effect=r.account_amount)))) RETURN;\nIF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_refund_scope s WHERE s.supplier_id=i.supplier_id AND s.currency_code=i.currency_code) OR created_by<>16 OR created_by IS NULL OR amount<=0 OR amount>100 OR purchase_invoice_id IS NOT NULL OR movement_type NOT IN(N''payment'',N''supplier_refund'',N''supplier_refund_cancel'')) AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_refund_scope s WHERE s.supplier_id=d.supplier_id) OR d.created_by<>16 OR d.movement_type<>N''payment'')) RETURN;  IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.supplier_id=i.supplier_id) OR amount<0 OR amount>1000) AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.supplier_id=d.supplier_id))) RETURN;  IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_payment_suppliers s WHERE s.supplier_id=i.supplier_id AND s.currency_code=i.currency_code) OR created_by<>16 OR created_by IS NULL OR amount<=0 OR amount>500 OR movement_type NOT IN(N''payment'',N''payment_cancel'',N''opening_balance'') OR (purchase_invoice_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.test_payment_invoices p WHERE p.invoice_id=i.purchase_invoice_id))) AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_payment_suppliers s WHERE s.supplier_id=d.supplier_id) OR d.movement_type NOT IN(N''payment'',N''payment_cancel'') OR d.created_by<>16)) RETURN;  SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i WHERE supplier_id<>(SELECT supplier_id FROM dbo.test_purchase_scope) OR movement_type NOT IN(N''purchase_invoice'',N''purchase_invoice_cancel'') OR NOT EXISTS(SELECT 1 FROM dbo.test_purchase_links l WHERE l.invoice_id=i.purchase_invoice_id) UNION ALL SELECT 1 FROM deleted WHERE supplier_id<>(SELECT supplier_id FROM dbo.test_purchase_scope)) THROW 51070,''TEST_PURCHASE_SCOPE_REQUIRED'',1; END;","after_hash":"2E9DEF9DD038511972F774271F44C20E8627FC53C1A4A754D99C0C80F7A04220"},{"name":"test_guard_suppliers","before_hash":"6FB2AE9534434693C49825B1EC7B15318FA40A567B042350DFF5F3F069E508A1","before_definition":"CREATE TRIGGER dbo.test_guard_suppliers ON dbo.suppliers AFTER INSERT,UPDATE,DELETE AS BEGIN IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_refund_scope s WHERE s.supplier_id=i.id AND s.currency_code=i.currency_code) OR balance < -100 OR balance>0) AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_refund_scope s WHERE s.supplier_id=d.id))) RETURN;  IF (SUSER_SNAME()<>N''melisa_sirket_sales_test_20260929_01'' AND NOT EXISTS(SELECT 1 FROM deleted) AND EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted WHERE supplier_code NOT IN(N''TEST-REFUND-TRY'',N''TEST-REFUND-USD'',N''TEST-REFUND-EUR'') OR balance<>0)) RETURN;  IF (SUSER_SNAME()<>N''melisa_sirket_sales_test_20260929_01'' AND NOT EXISTS(SELECT 1 FROM deleted) AND EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted WHERE supplier_code NOT IN(N''TEST-REV-RETURN-S'',N''TEST-REV-COUNT-S'') OR balance<>0)) RETURN;  IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.supplier_id=i.id) OR balance < -2000 OR balance>2000) AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.supplier_id=d.id))) RETURN;  IF (SUSER_SNAME()<>N''melisa_sirket_sales_test_20260929_01'' AND NOT EXISTS(SELECT 1 FROM deleted) AND EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted WHERE supplier_code NOT IN(N''TEST-DAILY-PUR-S'',N''TEST-DAILY-COUNT-S'') OR balance<>0)) RETURN;  IF (EXISTS(SELECT