TS(SELECT 1 FROM dbo.test_crm_order_requests r\n JOIN dbo.sales_orders o ON o.id=r.order_id JOIN dbo.users u ON u.id=r.actor_id\n JOIN dbo.customers c ON c.id=o.customer_id\n WHERE r.order_id=i.entity_id AND r.actor_id=i.actor_user_id AND u.is_active=1\n AND r.customer_id=593 AND c.id=593 AND c.customer_code=N''TEST-V70-20260929-C'' AND c.is_active=1 AND c.is_deleted=0\n AND r.conversation_id=N''55'' AND r.peer=N''905387217733'' AND o.status=N''draft''\n AND i.reason=N''CRM TEST draft only; verified CRM actor ''+r.crm_actor_id\n AND ISJSON(i.after_json)=1\n AND JSON_VALUE(i.after_json,''$.requestId'')=CONVERT(NVARCHAR(36),r.request_id)\n AND JSON_VALUE(i.after_json,''$.crmActorId'')=r.crm_actor_id\n AND JSON_VALUE(i.after_json,''$.conversationId'')=N''55'' AND JSON_VALUE(i.after_json,''$.peer'')=r.peer\n AND JSON_VALUE(i.after_json,''$.payloadHash'')=r.payload_hash\n AND TRY_CONVERT(BIGINT,JSON_VALUE(i.after_json,''$.orderId''))=r.order_id\n AND JSON_VALUE(i.after_json,''$.currency'')=o.document_currency\n AND TRY_CONVERT(DECIMAL(18,4),JSON_VALUE(i.after_json,''$.grandTotal''))=o.grand_total\n AND JSON_VALUE(i.after_json,''$.stockEffect'')=N''false'' AND JSON_VALUE(i.after_json,''$.ledgerEffect'')=N''false''\n AND EXISTS(SELECT 1 FROM OPENJSON(i.after_json) WHERE [key]=N''stockEffect'' AND [type]=3 AND [value]=N''false'')\n AND EXISTS(SELECT 1 FROM OPENJSON(i.after_json) WHERE [key]=N''ledgerEffect'' AND [type]=3 AND [value]=N''false'')\n AND NOT EXISTS(SELECT 1 FROM dbo.audit_logs a WHERE a.entity_type=N''sales_order'' AND a.entity_id=r.order_id AND a.source=N''crm-test'' AND a.id<>i.id)\n AND (SELECT COUNT(*) FROM inserted x WHERE x.entity_id=i.entity_id)=1)) RETURN;\n \n/* CANONICAL_LINKED_PURCHASE_RETURN_20261003 */\nIF EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM deleted)\n AND NOT EXISTS(SELECT 1 FROM inserted i WHERE i.actor_user_id IS NULL\n OR i.actor_user_id NOT IN(1,16) OR i.entity_type IS NULL OR i.entity_type<>N''invoice_return''\n OR NOT EXISTS(SELECT 1 FROM dbo.invoice_returns r\n JOIN dbo.test_purchase_links l ON l.invoice_id=r.source_purchase_invoice_id\n JOIN dbo.test_goods_receipts g ON g.id=l.goods_id\n JOIN dbo.test_purchase_scope t ON t.id=1\n JOIN dbo.purchase_invoices p ON p.id=l.invoice_id\n WHERE r.id=i.entity_id AND r.kind=N''purchase'' AND r.supplier_id=t.supplier_id\n AND g.state=N''accepted'' AND g.product_id=t.product_id AND g.supplier_id=t.supplier_id\n AND p.supplier_id=t.supplier_id AND p.document_no LIKE N''TSTG-%''\n AND r.status IN(N''finalized'',N''cancelled''))) RETURN;\nIF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM deleted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE actor_user_id<>16 OR actor_user_id IS NULL OR entity_type<>N''supplier_movement'' OR NOT EXISTS(SELECT 1 FROM dbo.supplier_movements m JOIN dbo.test_refund_scope s ON s.supplier_id=m.supplier_id WHERE m.id=i.entity_id))) RETURN;  IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM deleted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE actor_user_id NOT IN(15,16) OR actor_user_id IS NULL OR NOT((entity_type=N''test_daily_draft'' AND EXISTS(SELECT 1 FROM dbo.test_daily_drafts d WHERE d.id=i.entity_id)) OR(entity_type=N''product'' AND EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.product_id=i.entity_id)) OR(entity_type=N''invoice_return'' AND EXISTS(SELECT 1 FROM dbo.invoice_returns r JOIN dbo.test_daily_scope s ON s.customer_id=r.customer_id OR s.supplier_id=r.supplier_id WHERE r.id=i.entity_id)) OR(entity_type=N''sales_invoice'' AND EXISTS(SELECT 1 FROM dbo.sales_invoices r JOIN dbo.test_daily_scope s ON s.customer_id=r.customer_id WHERE r.id=i.entity_id)) OR(entity_type=N''purchase_invoice'' AND EXISTS(SELECT 1 FROM dbo.purchase_invoices r JOIN dbo.test_daily_scope s ON s.supplier_id=r.supplier_id WHERE r.id=i.entity_id)) OR(entity_type=N''customer_movement'' AND EXISTS(SELECT 1 FROM dbo.customer_movements r JOIN dbo.test_daily_scope s ON s.customer_id=r.customer_id WHERE r.id=i.entity_id)) OR(entity_type=N''supplier_movement'' AND EXISTS(SELECT 1 FROM dbo.supplier_movements r JOIN dbo.test_daily_scope s ON s.supplier_id=r.supplier_id WHERE r.id=i.entity_id))))) RETURN;  IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM deleted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE actor_user_id<>16 OR actor_user_id IS NULL OR entity_type<>N''supplier_movement'' OR NOT EXISTS(SELECT 1 FROM dbo.supplier_movements m JOIN dbo.test_payment_suppliers s ON s.supplier_id=m.supplier_id WHERE m.id=i.entity_id))) RETURN;  IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE actor_user_id NOT IN(SELECT seller_id FROM dbo.test_sales_scope UNION ALL SELECT ilker_id FROM dbo.test_sales_scope) OR actor_user_id IS NULL OR NOT((entity_type=N''test_goods_receipt'' AND EXISTS(SELECT 1 FROM dbo.test_goods_receipts g WHERE g.id=i.entity_id)) OR(entity_type=N''purchase_invoice'' AND EXISTS(SELECT 1 FROM dbo.purchase_invoices p WHERE p.id=i.entity_id AND p.supplier_id=(SELECT supplier_id FROM dbo.test_purchase_scope)))))) RETURN;\n IF EXISTS(SELECT 1 FROM inserted i WHERE NOT(\n ((actor_user_id=(SELECT seller_id FROM dbo.test_sales_scope) OR (actor_user_id=1 AND EXISTS(SELECT 1 FROM dbo.users u JOIN dbo.roles r ON r.id=u.role_id WHERE u.id=1 AND u.is_active=1 AND r.code=N''admin''))) AND entity_type=N''sales_invoice'' AND EXISTS(SELECT 1 FROM dbo.sales_invoices s WHERE s.id=i.entity_id AND s.document_no LIKE N''TST70-%'' AND s.customer_id=(SELECT customer_id FROM dbo.test_sales_scope))) OR\n (actor_user_id=(SELECT ilker_id FROM dbo.test_sales_scope) AND entity_type=N''customer_movement'' AND EXISTS(SELECT 1 FROM dbo.customer_movements m WHERE m.id=i.entity_id AND m.customer_id=(SELECT customer_id FROM dbo.test_sales_scope)))) OR actor_user_id IS NULL) THROW 51070,''TEST_FIXTURE_SCOPE_REQUIRED'',1;\nEND;\n","after_hash":"873E930E71CAE70DAA20483257A70A90F74DEA53B8F1D9D8A4B4AED295538EB4"},{"name":"test_guard_products","before_hash":"2ED4A073DBA8048763614E452ECFAD580BF52CB12B63184F2EB95887D7010C9D","before_definition":"CREATE TRIGGER dbo.test_guard_products ON dbo.products AFTER INSERT,UPDATE,DELETE AS BEGIN IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.product_id=i.id) OR stock_code NOT LIKE N''TEST-DAILY-%'' OR unit<>N''ADET'' OR current_stock_qty<0 OR current_stock_qty>40 OR average_cost_try<=0 OR average_cost_try>200) AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.product_id=d.id))) RETURN;  IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted WHERE id<>(SELECT product_id FROM dbo.test_purchase_scope) OR stock_code<>N''TEST-V70-GOODS-P'' OR unit<>N''ADET'' OR current_stock_qty<20 OR current_stock_qty>30 OR average_cost_try<>60) AND NOT EXISTS(SELECT 1 FROM deleted WHERE id<>(SELECT product_id FROM dbo.test_purchase_scope))) RETURN; SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted WHERE id<>(SELECT product_id FROM dbo.test_sales_scope) OR stock_code<>N''TEST-V70-20260929-P'' OR current_stock_qty<0 OR current_stock_qty>20 UNION ALL SELECT 1 FROM deleted WHERE id<>(SELECT product_id FROM dbo.test_sales_scope)) THROW 51070,''TEST_FIXTURE_SCOPE_REQUIRED'',1; END;","after_hash":"C303EB05895B1BC911AE9833BD20DC4953707B8E64B5F7E177E6A387F909FE68"},{"name":"test_guard_purchase_invoice_items","before_hash":"A0DCE53291E1AC6B3B9E31E1F43C451B907270641479D05300D84178F203775A","before_definition":"CREATE TRIGGER dbo.test_guard_purchase_invoice_items ON dbo.purchase_invoice_items AFTER INSERT,UPDATE,DELETE AS BEGIN IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.product_id=i.product_id) OR quantity<=0 OR quantity>10) AND NOT EXISTS(SELECT 1 FROM deleted)) RETURN;  SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted WHERE product_id<>(SELECT product_id FROM dbo.test_purchase_scope) OR quantity<=0 OR quantity>5 OR purchase_price<>60 OR currency_code<>N''TRY'') THROW 51070,''TEST_PURCHASE_SCOPE_REQUIRED'',1; END;","after_hash":"58BAF43BD6BF9235FDED652692AB3EA8C7ABD846980FC4155D63D5E12661DDF3"},{"name":"test_guard_purchase_invoices","before_hash":"C93D7228853EFF97F417E1A1C7BC63001550572AAC0C6AEAD9DBFA3566CDC909","before_definition":"CREATE TRIGGER dbo.test_guard_purchase_invoices ON dbo.purchase_invoices AFTER INSERT,UPDATE,DELETE AS BEGIN IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.supplier_id=i.supplier_id) OR document_no NOT LIKE N''TDAY-%'' OR grand_total<0 OR grand_total>1000) AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.supplier_id=d.supplier_id))) RETURN;  SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted WHERE supplier_id<>(SELECT supplier_id FROM dbo.test_purchase_scope) OR document_no NOT LIKE N''TSTG-%'' OR grand_total<0 OR grand_total>300 OR document_currency<>N''TRY'' UNION ALL SELECT 1 FROM deleted WHERE supplier_id<>(SELECT supplier_id FROM dbo.test_purchase_scope)) THROW 51070,''TEST_PURCHASE_SCOPE_REQUIRED'',1; END;","after_hash":"AF7FC59573D2112F4DD1F7730F78AD86FB119F74D5E2141818CFE54FB5F1D8FC"},{"name":"test_guard_stock_movements","before_hash":"173000C24D3D6A44A928584F35D1E41B6661E01CA3E5C6F6E14A785C54C449B9","before_definition":"CREATE TRIGGER dbo.test_guard_stock_movements ON dbo.stock_movements AFTER INSERT,UPDATE,DELETE AS BEGIN \n/* CANONICAL_LINKED_PURCHASE_RETURN_20261003 */\nIF EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM deleted)\n AND NOT EXISTS(SELECT 1 FROM inserted i WHERE i.created_by IS NULL OR i.created_by NOT IN(1,16)\n OR i.source_type NOT IN(N''invoice_return'',N''invoice_return_cancel'')\n OR NOT EXISTS(SELECT 1 FROM dbo.invoice_returns r\n JOIN dbo.invoice_return_items ri ON ri.invoice_return_id=r.id\n JOIN dbo.test_purchase_links l ON l.invoice_id=r.source_purchase_invoice_id\n JOIN dbo.test_goods_receipts g ON g.id=l.goods_id\n JOIN dbo.test_purchase_scope t ON t.id=1\n JOIN dbo.purchase_invoices p ON p.id=l.invoice_id\n WHERE r.id=i.source_id AND r.kind=N''purchase'' AND r.status=N''finalized''\n AND r.supplier_id=t.supplier_id AND p.supplier_id=t.supplier_id\n AND g.state=N''accepted'' AND g.product_id=t.product_id AND g.supplier_id=t.supplier_id\n AND p.document_no LIKE N''TSTG-%'' AND ri.product_id=t.product_id\n AND i.product_id=ri.product_id AND i.supplier_id=r.supplier_id\n AND i.currency_code=N''TRY'' AND i.unit_cost_try=ri.unit_cost_try AND ri.unit_cost_try=60\n AND ri.quantity>0 AND ri.quantity<=5\n AND ((i.source_type=N''invoice_return'' AND p.status=N''finalized''\n AND i.quantity_net=-ri.quantity AND i.quantity_out=ri.quantity AND i.quantity_in=0 AND i.amount_try=-ri.amount_try)\n OR (i.source_type=N''invoice_return_cancel'' AND i.quantity_net=ri.quantity\n AND i.quantity_in=ri.quantity AND i.quantity_out=0 AND i.amount_try=ri.amount_try)))) RETURN;\nIF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM deleted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.product_id=i.product_id) OR ABS(quantity_net)>20 OR unit_cost_try<=0 OR unit_cost_try>200)) RETURN;  IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE product_id<>(SELECT product_id FROM dbo.test_purchase_scope) OR source_type<>N''goods_receipt'' OR quantity_out<>0 OR quantity_in<>quantity_net OR created_by<>(SELECT ilker_id FROM dbo.test_sales_scope) OR warehouse_name<>N''TEST V70 MAL KABUL DEPOSU'' OR NOT EXISTS(SELECT 1 FROM dbo.test_goods_receipts g WHERE g.id=i.source_id AND g.state=N''accepted'' AND g.quantity=i.quantity_net))) RETURN; SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i WHERE product_id<>(SELECT product_id FROM dbo.test_sales_scope) OR source_type NOT IN(N''sales_invoice'',N''sales_invoice_cancel'') OR NOT EXISTS(SELECT 1 FROM dbo.sales_invoices s WHERE s.id=i.source_id AND s.document_no LIKE N''TST70-%'' AND s.customer_id=(SELECT customer_id FROM dbo.test_sales_scope))) THROW 51070,''TEST_FIXTURE_SCOPE_REQUIRED'',1; END;","after_hash":"CD8CCEDAC7C0E6D17B4843A9982B4EA59C4FA772C2CD942E50D671B5DE126B3B"},{"name":"test_guard_supplier_movements","before_hash":"328288D01F6AA3D96724617FC723849A7B884A04E095539F56D3FFA137BCE159","before_definition":"CREATE TRIGGER dbo.test_guard_supplier_movements ON dbo.supplier_movements AFTER INSERT,UPDATE,DELETE AS BEGIN \n/* CANONICAL_LINKED_PURCHASE_RETURN_20261003 */\nIF EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM deleted)\n AND NOT EXISTS(SELECT 1 FROM inserted i WHERE i.created_by IS NULL OR i.created_by NOT IN(1,16)\n OR i.movement_type NOT IN(N''purchase_return'',N''purchase_return_cancel'')\n OR NOT EXISTS(SELECT 1 FROM dbo.invoice_returns r\n JOIN dbo.test_purchase_links l ON l.invoice_id=r.source_purchase_invoice_id\n JOIN dbo.test_goods_receipts g ON g.id=l.goods_id\n JOIN dbo.test_purchase_scope t ON t.id=1\n JOIN dbo.purchase_invoices p ON p.id=l.invoice_id\n WHERE r.id=i.invoice_return_id AND r.kind=N''purchase'' AND r.status=N''finalized''\n AND r.supplier_id=t.supplier_id AND i.supplier_id=t.supplier_id\n AND g.state=N''accepted'' AND g.product_id=t.product_id AND g.supplier_id=t.supplier_id\n AND p.supplier_id=t.supplier_id AND p.document_no LIKE N''TSTG-%''\n AND i.currency_code=N''TRY'' AND i.account_currency=N''TRY''\n AND i.amount=r.amount AND i.account_amount=r.account_amount AND i.amount_try=r.amount_try\n AND i.document_exchange_rate_snapshot=r.exchange_rate_snapshot\n AND i.account_exchange_rate_snapshot=r.account_exchange_rate_snapshot\n AND ((i.movement_type=N''purchase_return'' AND p.status=N''finalized'' AND i.balance_effect=-r.account_amount)\n OR (i.movement_type=N''purchase_return_cancel'' AND i.balance_effect=r.account_amount)))) RETURN;\nIF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_refund_scope s WHERE s.supplier_id=i.supplier_id AND s.currency_code=i.currency_code) OR created_by<>16 OR created_by IS NULL OR amount<=0 OR amount>100 OR purchase_invoice_id IS NOT NULL OR movement_type NOT IN(N''payment'',N''supplier_refund'',N''supplier_refund_cancel'')) AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_refund_scope s WHERE s.supplier_id=d.supplier_id) OR d.created_by<>16 OR d.movement_type<>N''payment'')) RETURN;  IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.supplier_id=i.supplier_id) OR amount<0 OR amount>1000) AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.supplier_id=d.supplier_id))) RETURN;  IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_payment_suppliers s WHERE s.supplier_id=i.supplier_id AND s.currency_code=i.currency_code) OR created_by<>16 OR created_by IS NULL OR amount<=0 OR amount>500 OR movement_type NOT IN(N''payment'',N''payment_cancel'',N''opening_balance'') OR (purchase_invoice_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.test_payment_invoices p WHERE p.invoice_id=i.purchase_invoice_id))) AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_payment_suppliers s WHERE s.supplier_id=d.supplier_id) OR d.movement_type NOT IN(N''payment'',N''payment_cancel'') OR d.created_by<>16)) RETURN;  SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i WHERE supplier_id<>(SELECT supplier_id FROM dbo.test_purchase_scope) OR movement_type NOT IN(N''purchase_invoice'',N''purchase_invoice_cancel'') OR NOT EXISTS(SELECT 1 FROM dbo.test_purchase_links l WHERE l.invoice_id=i.purchase_invoice_id) UNION ALL SELECT 1 FROM deleted WHERE supplier_id<>(SELECT supplier_id FROM dbo.test_purchase_scope)) THROW 51070,''TEST_PURCHASE_SCOPE_REQUIRED'',1; END;","after_hash":"2E9DEF9DD038511972F774271F44C20E8627FC53C1A4A754D99C0C80F7A04220"},{"name":"test_guard_suppliers","before_hash":"6FB2AE9534434693C49825B1EC7B15318FA40A567B042350DFF5F3F069E508A1","before_definition":"CREATE TRIGGER dbo.test_guard_suppliers ON dbo.suppliers AFTER INSERT,UPDATE,DELETE AS BEGIN IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_refund_scope s WHERE s.supplier_id=i.id AND s.currency_code=i.currency_code) OR balance < -100 OR balance>0) AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_refund_scope s WHERE s.supplier_id=d.id))) RETURN;  IF (SUSER_SNAME()<>N''melisa_sirket_sales_test_20260929_01'' AND NOT EXISTS(SELECT 1 FROM deleted) AND EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted WHERE supplier_code NOT IN(N''TEST-REFUND-TRY'',N''TEST-REFUND-USD'',N''TEST-REFUND-EUR'') OR balance<>0)) RETURN;  IF (SUSER_SNAME()<>N''melisa_sirket_sales_test_20260929_01'' AND NOT EXISTS(SELECT 1 FROM deleted) AND EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted WHERE supplier_code NOT IN(N''TEST-REV-RETURN-S'',N''TEST-REV-COUNT-S'') OR balance<>0)) RETURN;  IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.supplier_id=i.id) OR balance < -2000 OR balance>2000) AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_daily_scope s WHERE s.supplier_id=d.id))) RETURN;  IF (SUSER_SNAME()<>N''melisa_sirket_sales_test_20260929_01'' AND NOT EXISTS(SELECT 1 FROM deleted) AND EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted WHERE supplier_code NOT IN(N''TEST-DAILY-PUR-S'',N''TEST-DAILY-COUNT-S'') OR balance<>0)) RETURN;  IF (EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.test_payment_suppliers s WHERE s.supplier_id=i.id AND s.currency_code=i.currency_code) OR balance < -500 OR balance>600 OR supplier_code NOT LIKE N''TEST-V70-%'') AND NOT EXISTS(SELECT 1 FROM deleted d WHERE NOT EXISTS(SELECT 1 FROM dbo.test_payment_suppliers s WHERE s.supplier_id=d.id))) RETURN;  IF (SUSER_SNAME()<>N''melisa_sirket_sales_test_20260929_01'' AND NOT EXISTS(SELECT 1 FROM deleted) AND EXISTS(SELECT 1 FROM inserted) AND NOT EXISTS(SELECT 1 FROM inserted WHERE supplier_code NOT IN(N''TEST-V70-PAY-USD'',N''TEST-V70-PAY-EUR'') OR balance<>300)) RETURN;  SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted WHERE id<>(SELECT supplier_id FROM dbo.test_purchase_scope) OR supplier_code<>N''TEST-V70-GOODS-S'' OR currency_code<>N''TRY'' OR balance<0 OR balance>600 UNION ALL SELECT 1 FROM deleted WHERE id<>(SELECT supplier_id FROM dbo.test_purchase_scope)) THROW 51070,''TEST_PURCHASE_SCOPE_REQUIRED'',1; END;","after_hash":"201398D0AD53D8FA50F99C78699C13ECFF875F9D5E6787777961A31788910314"},{"name":"test_guard_test_purchase_requests","before_hash":"39FFC4C7F07F496A078AA81CD9D243CB3B51A7B050D6F5D1B12C18D47872D4B0","before_definition":"CREATE TRIGGER dbo.test_guard_test_purchase_requests ON dbo.test_purchase_requests AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted WHERE actor_id NOT IN(15,16) OR operation NOT IN(N''goods_create'',N''goods_approve'',N''goods_reject'',N''purchase_create'',N''purchase_cancel'')) THROW 51070,''TEST_PURCHASE_SCOPE_REQUIRED'',1; END;","after_hash":"FEF624D00B624BD8A3FE2666FD21AD31BE041E9404E89DC8AA89754345C800A8"}]',N'[{"name":"c03_guard_audit","definition_hash":"FBD16D7B8476D7079F5432215332912AB3AC24C55D17794ED8CB5C8FE3FB6596"},{"name":"c03_guard_daily_receipts","definition_hash":"837726152A01192C719D030A2FF6E78170537F6325CC1474F10A901B251F2623"},{"name":"c03_guard_headers","definition_hash":"030382C696E622667B0752DC6BD96AB4DA6369478189FF5A7C7D946DED5D8F67"},{"name":"c03_guard_intents","definition_hash":"1E16AFBAE063DB8B76064E6F08C5D2F40663D0AB789