CREATE TABLE dbo.work_trade_guard_manifest(name sysname NOT NULL PRIMARY KEY,before_hash varchar(64) NULL,before_definition nvarchar(max) NULL,after_hash varchar(64) NOT NULL);
CREATE TABLE dbo.work_trade_scope(id int NOT NULL PRIMARY KEY CHECK(id=1),run_id nvarchar(40) NOT NULL,customer_id bigint NOT NULL REFERENCES dbo.customers(id),account_id bigint NOT NULL REFERENCES dbo.finance_accounts(id),currency nvarchar(3) NOT NULL CHECK(currency=N'TRY'),document_date date NOT NULL,max_total decimal(18,4) NOT NULL CHECK(max_total=500),max_quantity int NOT NULL CHECK(max_quantity=5),max_operations int NOT NULL CHECK(max_operations=30));
CREATE TABLE dbo.work_trade_products(product_id bigint NOT NULL PRIMARY KEY REFERENCES dbo.products(id),stock_code nvarchar(80) NOT NULL UNIQUE,name nvarchar(200) NOT NULL,barcode nvarchar(80) NOT NULL UNIQUE,initial_stock decimal(18,3) NOT NULL CHECK(initial_stock=20),unit nvarchar(20) NOT NULL CHECK(unit=N'ADET'),unit_price decimal(18,8) NOT NULL CHECK(unit_price IN(100,50)),cost decimal(18,4) NOT NULL CHECK(cost IN(60,30)),price_id bigint NOT NULL UNIQUE REFERENCES dbo.product_prices(id));
CREATE TABLE dbo.work_trade_requests(request_id uniqueidentifier NOT NULL PRIMARY KEY,actor_id bigint NOT NULL,operation nvarchar(30) NOT NULL,payload_hash char(64) NOT NULL,payload_json nvarchar(max) NOT NULL CHECK(ISJSON(payload_json)=1),response_json nvarchar(max) NOT NULL CHECK(ISJSON(response_json)=1),created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.work_sales_links(invoice_id bigint NOT NULL PRIMARY KEY REFERENCES dbo.sales_invoices(id),request_id uniqueidentifier NOT NULL UNIQUE,actor_id bigint NOT NULL,preview_json nvarchar(max) NOT NULL CHECK(ISJSON(preview_json)=1));
CREATE TABLE dbo.work_collection_links(movement_id bigint NOT NULL PRIMARY KEY REFERENCES dbo.customer_movements(id),invoice_id bigint NOT NULL REFERENCES dbo.work_sales_links(invoice_id),request_id uniqueidentifier NOT NULL UNIQUE,original_id bigint NULL REFERENCES dbo.work_collection_links(movement_id));
CREATE UNIQUE INDEX work_collection_one_reversal ON dbo.work_collection_links(original_id) WHERE original_id IS NOT NULL;
CREATE TABLE dbo.work_trade_intents(session_id int NOT NULL PRIMARY KEY,request_id uniqueidentifier NOT NULL UNIQUE,actor_id bigint NOT NULL,operation nvarchar(30) NOT NULL,payload_json nvarchar(max) NOT NULL CHECK(ISJSON(payload_json)=1),invoice_id bigint NULL REFERENCES dbo.sales_invoices(id));

SET @nightDefinition=REPLACE(CAST(N'CREATE PROCEDURE dbo.work_trade_assert_ready WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON; IF DB_NAME() COLLATE Latin1_General_100_BIN2<>N''MELISA_ERP_SIRKET_TEST_20260929_01'' OR CAST(SERVERPROPERTY(''ServerName'') AS nvarchar(128)) COLLATE Latin1_General_100_BIN2<>N''Semih\MELISADEV'' THROW 51106,''WRONG_WORK_NIGHT_TARGET'',1;
IF (SELECT CONVERT(varchar(64),HASHBYTES(''SHA2_256'',STRING_AGG(CONVERT(nvarchar(max),CONCAT(name,N''|'',CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(object_id)),2),N''|'',is_disabled,N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger''))),N'';'') WITHIN GROUP(ORDER BY name)),2) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' OR name LIKE N''immutable[_]operation[_]%'' OR name LIKE N''immutable[_]accepted[_]%'')<>''9AE41CA1AB25EE165019AD04DBD9A6FB4E5B7190F027E0A07A87FB03D698379E'' THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF (SELECT COUNT(*) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' AND is_disabled=0 AND OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger'')=1 AND OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger'')=1 AND OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger'')=1)<>37 THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF NOT EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_manifest WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND sealed=1 AND seal_hash=''69ff490f2938e34aa2f10399a5cf7b8042950667780779a15d708188c4b90de7'' AND source_rows=176 AND native_holds=172 AND not_present=4) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF NOT EXISTS(SELECT 1 FROM erp_migration.accepted_price_manifest WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND sealed=1 AND product_count=16622 AND price_count=63774 AND source_hash=''36971dab7296dd171ee0084c185f833b47b96d6a47fe57c8486a2b81d78ef400'' AND plan_hash=''18639c27f276f4263d5e9a6b5037753c78f2c3d341a053055db7cb7b00da2f0a'' AND bindings_hash=''5842be926d493c8973566fd922ef840d9fe6f7cecd9d83f17f506be5aa3fbd72'') THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF (SELECT COUNT(*) FROM dbo.test_purchase_batch_guard_manifest)<>15 OR EXISTS(SELECT 1 FROM dbo.test_purchase_batch_guard_manifest m LEFT JOIN sys.triggers t ON t.object_id=OBJECT_ID(N''dbo.''+m.name) WHERE t.object_id IS NULL OR t.is_disabled=1 OR m.after_hash<>CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(t.object_id)),2)) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF (SELECT COUNT(*) FROM dbo.test_purchase_fx_guard_manifest)<>17 OR EXISTS(SELECT 1 FROM dbo.test_purchase_fx_guard_manifest m LEFT JOIN sys.objects o ON o.object_id=OBJECT_ID(N''dbo.''+m.name) WHERE o.object_id IS NULL OR m.definition_hash<>CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(o.object_id)),2) OR (o.type=N''TR'' AND OBJECTPROPERTY(o.object_id,''ExecIsTriggerDisabled'')<>0)) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF NOT EXISTS(SELECT 1 FROM dbo.work_trade_install_state WHERE id=1 AND run_id=N''ERP-NIGHT-20261006'' AND sealed=1) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF (SELECT COUNT(*) FROM dbo.work_trade_guard_manifest)<>22 OR (SELECT COUNT(*) FROM dbo.work_trade_guard_manifest WHERE name IN(N''work_trade_assert_ready'',N''work_trade_get_context'',N''work_trade_assert_effects''))<>3 OR (SELECT COUNT(*) FROM dbo.work_trade_guard_manifest WHERE name LIKE N''test[_]guard[_]%'')<>9 OR (SELECT COUNT(*) FROM dbo.work_trade_guard_manifest WHERE name LIKE N''work[_]night[_]guard[_]%'')<>10 THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF EXISTS(SELECT 1 FROM dbo.work_trade_guard_manifest m LEFT JOIN sys.objects o ON o.object_id=OBJECT_ID(N''dbo.''+m.name) WHERE o.object_id IS NULL OR m.after_hash<>CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(o.object_id)),2) OR (o.type=N''TR'' AND OBJECTPROPERTY(o.object_id,''ExecIsTriggerDisabled'')<>0)) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF (SELECT COUNT(*) FROM dbo.work_trade_scope)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.work_trade_scope WHERE id=1 AND run_id=N''ERP-NIGHT-20261006'' AND currency=N''TRY'' AND document_date=CONVERT(date,N''2026-10-06'') AND max_total=500 AND max_quantity=5 AND max_operations=30) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF (SELECT COUNT(*) FROM dbo.work_trade_products)<>2 OR EXISTS(SELECT 1 FROM dbo.work_trade_products s LEFT JOIN dbo.products p ON p.id=s.product_id LEFT JOIN dbo.product_prices r ON r.id=s.price_id WHERE p.id IS NULL OR r.id IS NULL OR p.average_cost_try IS NULL OR r.price IS NULL OR r.product_id IS NULL OR r.price_type IS NULL OR r.price_tier IS NULL OR r.currency_code IS NULL OR p.stock_code COLLATE Latin1_General_100_BIN2<>s.stock_code OR p.name<>s.name OR p.unit<>N''ADET'' OR p.currency_code<>N''TRY'' OR p.is_active<>1 OR p.is_deleted<>0 OR p.current_stock_qty<0 OR p.current_stock_qty>s.initial_stock OR p.average_cost_try<>s.cost OR p.purchase_price<>s.cost OR p.sales_price<>s.unit_price OR p.source_record_key IS NOT NULL OR p.migration_run_id IS NOT NULL OR p.supplier_id IS NOT NULL OR r.product_id<>p.id OR r.price_type<>N''sales'' OR r.price_tier<>1 OR r.currency_code<>N''TRY'' OR r.price<>s.unit_price OR r.source_record_key IS NOT NULL OR r.migration_run_id IS NOT NULL) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF NOT EXISTS(SELECT 1 FROM dbo.work_trade_scope s JOIN dbo.customers c ON c.id=s.customer_id JOIN dbo.finance_accounts a ON a.id=s.account_id WHERE c.customer_code=N''TEST-NIGHT-20261006-C'' AND c.name=N''Deneme kaydı — Gece müşterisi'' AND c.currency_code=N''TRY'' AND c.balance BETWEEN 0 AND 15000 AND c.is_active=1 AND c.is_deleted=0 AND c.source_record_key IS NULL AND c.migration_run_id IS NULL AND a.account_code=N''TEST-NIGHT-20261006-K'' AND a.account_name=N''Deneme kaydı — Gece kasası'' AND a.account_type=N''cash'' AND a.currency_code=N''TRY'' AND a.opening_balance=0 AND a.current_balance BETWEEN 0 AND 15000 AND a.is_active=1 AND a.source_record_key IS NULL AND a.migration_run_id IS NULL) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds h WHERE (h.entity=N''product'' AND EXISTS(SELECT 1 FROM dbo.work_trade_products p WHERE p.product_id=h.native_id)) OR (h.entity=N''customer'' AND h.native_id=(SELECT customer_id FROM dbo.work_trade_scope WHERE id=1))) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
END;' AS nvarchar(max)),NCHAR(13)+NCHAR(10),NCHAR(10));EXEC sys.sp_executesql @nightDefinition;

SET @nightDefinition=REPLACE(CAST(N'CREATE PROCEDURE dbo.work_trade_get_context @actor_id int WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON; EXEC dbo.work_trade_assert_ready;
IF NOT EXISTS(SELECT 1 FROM dbo.users u JOIN dbo.roles r ON r.id=u.role_id WHERE u.id=@actor_id AND u.is_active=1 AND ((u.id=15 AND r.code=N''isolated_test_sales'') OR (u.id=16 AND r.code=N''isolated_test_ilker''))) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
SELECT (SELECT JSON_QUERY((SELECT CONVERT(varchar(20),c.id) id,c.customer_code code,c.name,c.currency_code currency,CONVERT(varchar(40),CAST(c.balance AS decimal(18,4))) balanceExact4 FROM dbo.customers c WHERE c.id=s.customer_id FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) customer,
JSON_QUERY((SELECT CONVERT(varchar(20),p.id) id,p.stock_code stockCode,p.name,w.barcode,p.unit,CONVERT(varchar(40),CAST(p.current_stock_qty AS decimal(18,3))) stockQuantityExact3,CONVERT(varchar(40),CAST(r.price AS decimal(18,8))) unitPriceExact8,CONVERT(varchar(40),CAST(p.average_cost_try AS decimal(18,4))) costExact4,CONVERT(varchar(20),r.id) priceId FROM dbo.work_trade_products w JOIN dbo.products p ON p.id=w.product_id JOIN dbo.product_prices r ON r.id=w.price_id ORDER BY p.id FOR JSON PATH)) products,
JSON_QUERY((SELECT CONVERT(varchar(20),a.id) id,a.account_code code,a.account_name name,a.account_type type,a.currency_code currency,CONVERT(varchar(40),CAST(a.current_balance AS decimal(18,4))) balanceExact4 FROM dbo.finance_accounts a WHERE a.id=s.account_id FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) account,
CONVERT(char(10),s.document_date,23) documentDate,s.currency,CONVERT(varchar(40),CAST(s.max_total AS decimal(18,4))) maxTotalExact4,s.max_quantity maxQuantity,s.max_operations maxOperations,
JSON_QUERY((SELECT N''[''+STRING_AGG(CONVERT(nvarchar(max),N''"''+STRING_ESCAPE(p.permission_key,''json'')+N''"''),N'','') WITHIN GROUP(ORDER BY p.permission_key)+N'']'' FROM dbo.permissions p JOIN dbo.users u ON u.role_id=p.role_id WHERE u.id=@actor_id AND u.is_active=1 AND p.can_view=1)) permissions,
LOWER(CONVERT(varchar(64),HASHBYTES(''SHA2_256'',CONCAT(s.run_id,N''|'',s.customer_id,N''|'',s.account_id,N''|'',(SELECT balance FROM dbo.customers WHERE id=s.customer_id),N''|'',(SELECT current_balance FROM dbo.finance_accounts WHERE id=s.account_id),N''|'',(SELECT STRING_AGG(CONVERT(nvarchar(max),CONCAT(p.id,N''|'',p.stock_code,N''|'',p.current_stock_qty,N''|'',r.id,N''|'',r.price)),N'';'') WITHIN GROUP(ORDER BY p.id) FROM dbo.work_trade_products w JOIN dbo.products p ON p.id=w.product_id JOIN dbo.product_prices r ON r.id=w.price_id))),2)) revision
FROM dbo.work_trade_scope s WHERE s.id=1 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER) context_json,
CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.work_trade_assert_ready''))),2) readyHash,
CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.work_trade_get_context''))),2) contextHash,
CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(OBJECT_ID(N''dbo.work_trade_assert_effects''))),2) effectsHash;
END;' AS nvarchar(max)),NCHAR(13)+NCHAR(10),NCHAR(10));EXEC sys.sp_executesql @nightDefinition;

SET @nightDefinition=REPLACE(CAST(N'CREATE PROCEDURE dbo.work_trade_assert_effects @request_id uniqueidentifier WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON; EXEC dbo.work_trade_assert_ready;
DECLARE @operation nvarchar(40),@invoice bigint,@actor bigint;
SELECT @operation=operation,@invoice=invoice_id,@actor=actor_id FROM dbo.work_trade_intents WHERE session_id=@@SPID AND request_id=@request_id;
IF @operation IS NULL OR @invoice IS NULL OR @actor NOT IN(15,16) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF @operation=N''sale_draft'' AND EXISTS(SELECT 1 FROM dbo.work_trade_intents n WHERE n.session_id=@@SPID AND (JSON_VALUE(n.payload_json,''$.customerId'')<>CONVERT(varchar(20),(SELECT customer_id FROM dbo.work_trade_scope)) OR JSON_VALUE(n.payload_json,''$.documentDate'')<>N''2026-10-06'' OR JSON_VALUE(n.payload_json,''$.currency'')<>N''TRY'' OR (SELECT COUNT(*) FROM OPENJSON(n.payload_json,''$.items''))<>(SELECT COUNT(*) FROM dbo.sales_invoice_items WHERE sales_invoice_id=@invoice) OR EXISTS(SELECT 1 FROM dbo.sales_invoice_items i WHERE i.sales_invoice_id=@invoice AND NOT EXISTS(SELECT 1 FROM OPENJSON(n.payload_json,''$.items'') WITH(productId varchar(20),quoteId varchar(20),quantityExact3 varchar(40)) x JOIN dbo.work_trade_products w ON CONVERT(varchar(20),w.product_id)=x.productId WHERE i.product_id=w.product_id AND CONVERT(varchar(20),w.price_id)=x.quoteId AND TRY_CONVERT(decimal(18,3),x.quantityExact3)=i.quantity)))) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF @operation IN(N''sale_finalize'',N''sale_cancel'') AND NOT EXISTS(SELECT 1 FROM dbo.work_trade_intents n WHERE n.session_id=@@SPID AND TRY_CONVERT(bigint,JSON_VALUE(n.payload_json,''$.id''))=@invoice) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF @operation=N''collection_create'' AND NOT EXISTS(SELECT 1 FROM dbo.work_trade_intents n WHERE n.session_id=@@SPID AND n.actor_id=16 AND TRY_CONVERT(bigint,JSON_VALUE(n.payload_json,''$.invoiceId''))=@invoice AND TRY_CONVERT(bigint,JSON_VALUE(n.payload_json,''$.accountId''))=(SELECT account_id FROM dbo.work_trade_scope) AND JSON_VALUE(n.payload_json,''$.documentDate'')=N''2026-10-06'') THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF NOT EXISTS(SELECT 1 FROM dbo.work_sales_links l JOIN dbo.sales_invoices v ON v.id=l.invoice_id JOIN dbo.work_trade_scope s ON s.customer_id=v.customer_id WHERE l.invoice_id=@invoice AND v.document_no LIKE N''NIGHT-%'' AND v.document_date=s.document_date AND v.document_currency=N''TRY'' AND v.customer_currency=N''TRY'' AND v.exchange_rate_snapshot=1 AND v.discount_rate=0 AND v.discount_total=0 AND v.grand_total=v.subtotal AND v.amount_try=v.grand_total AND v.grand_total>0 AND v.grand_total<=s.max_total AND v.is_migrated=0 AND v.affects_inventory=1 AND v.source_record_key IS NULL AND v.migration_run_id IS NULL) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF (SELECT COUNT(*) FROM dbo.sales_invoice_items WHERE sales_invoice_id=@invoice) NOT BETWEEN 1 AND 2 OR EXISTS(SELECT 1 FROM dbo.sales_invoice_items i WHERE i.sales_invoice_id=@invoice AND NOT EXISTS(SELECT 1 FROM dbo.work_trade_products w WHERE w.product_id=i.product_id AND i.stock_code_snapshot COLLATE Latin1_General_100_BIN2=w.stock_code AND i.product_name_snapshot=w.name AND i.barcode_snapshot=w.barcode AND i.quantity BETWEEN 1 AND 5 AND i.quantity=FLOOR(i.quantity) AND i.currency_code=N''TRY'' AND i.unit_price=w.unit_price AND i.line_total=i.quantity*w.unit_price AND i.average_cost_try_snapshot=w.cost AND i.source_record_key IS NULL AND i.migration_run_id IS NULL)) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF EXISTS(SELECT 1 FROM dbo.sales_invoices v WHERE v.id=@invoice AND v.grand_total<>(SELECT SUM(i.line_total) FROM dbo.sales_invoice_items i WHERE i.sales_invoice_id=v.id)) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF EXISTS(SELECT 1 FROM dbo.work_trade_products w JOIN dbo.products p ON p.id=w.product_id WHERE p.current_stock_qty<>w.initial_stock+COALESCE((SELECT SUM(m.quantity_net) FROM dbo.stock_movements m WHERE m.product_id=p.id),0)) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF EXISTS(SELECT 1 FROM dbo.work_trade_scope s JOIN dbo.customers c ON c.id=s.customer_id WHERE c.balance<>COALESCE((SELECT SUM(m.balance_effect) FROM dbo.customer_movements m WHERE m.customer_id=c.id),0)) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF EXISTS(SELECT 1 FROM dbo.work_trade_scope s JOIN dbo.finance_accounts a ON a.id=s.account_id WHERE a.current_balance<>COALESCE((SELECT SUM(CASE m.direction WHEN N''in'' THEN m.amount ELSE -m.amount END) FROM dbo.finance_account_movements m WHERE m.account_id=a.id),0)) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
IF EXISTS(SELECT 1 FROM dbo.work_sales_links l JOIN dbo.sales_invoices v ON v.id=l.invoice_id WHERE (SELECT COALESCE(SUM(CASE m.movement_type WHEN N''collection'' THEN m.amount WHEN N''collection_cancel'' THEN -m.amount ELSE 0 END),0) FROM dbo.customer_movements m WHERE m.sales_invoice_id=v.id)<0 OR (SELECT COALESCE(SUM(CASE m.movement_type WHEN N''collection'' THEN m.amount WHEN N''collection_cancel'' THEN -m.amount ELSE 0 END),0) FROM dbo.customer_movements m WHERE m.sales_invoice_id=v.id)>CASE WHEN v.status=N''finalized'' THEN v.grand_total ELSE 0 END) THROW 51106,''WORK_NIGHT_SCOPE_REQUIRED'',1;
